43	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
44	
45	export interface PickingBipItem {
46	  id: number;
47	  produto_nome: string;
48	  masterId?: number;
49	  quantidade: number;
50	  quantidade_enviada?: string;
51	  coletado: boolean;
52	  selectedBatches?: Record<string, number>;
53	  availableBatches?: Array<{ id: string; lote_id: string; quantidade: number; lotes: { id: string; codigo: string } }>;
54	  // Unidade do PEDIDO. Decide se cada bip soma +1 (caixa) ou +quantidade_interna (kg, un).
55	  unidade_medida?: string | null;
56	}
57	
58	
59	export interface BipApplied {
60	  itemId: number;
61	  produtoNome: string;
62	  uid: string;
63	  qty: number;
64	  /** Unidade INTERNA da etiqueta (un, kg, g). Em "Caixa com 12 un" = "un". */
65	  embalagem: string | null;
66	  /** Tipo do CONTAINER físico (caixa, saco, balde…). Usado na UI ao invés de embalagem. */
67	  tipoEmbalagem: string | null;
68	  /** Qty INTERNA da etiqueta (12, 5, etc). Pra mostrar "1 caixa (12 un)". */
69	  qtyInterna: number;
70	  loteId: string | null;
71	  bipadoAt: number;
72	}
