117	        etiqueta?: {
118	          produto_master_id: number;
119	          produto_nome_snapshot?: string | null;
120	          lote_id?: string | null;
121	          quantidade_interna?: number;
122	          embalagem_nome?: string | null;
123	          tipo_embalagem?: string | null;
124	        };
125	      } | null;
126	      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
127	        playErrorSound();
128	        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
129	        return;
130	      }
131	
132	      const scannedPid = rpc.etiqueta.produto_master_id;
133	      const qtyEtiquetaReal = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
134	      const scannedLote = rpc.etiqueta.lote_id ?? null;
135	      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
136	      const scannedTipoEmb = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;
137	      const scannedNome = rpc.etiqueta.produto_nome_snapshot || produtoNome;
138	
139	      const targetReal = items.find((i) => i.masterId === scannedPid);
140	      if (!targetReal) {
141	        uidsLidosRef.current.add(uid);
142	        toast.warning(`${scannedNome} transferido mas NÃO está na lista — registrado como extra`);
143	        return;
