213	      const novaQtdPrev = baseAtual + qtyEstimada;
214	      if (novaQtdPrev > target.quantidade) {
215	        const sobra = novaQtdPrev - target.quantidade;
216	        const confirmed = await new Promise<boolean>((resolve) => {
